-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "fc00b286-32f5-49f7-bef2-f8d384db05dd", "source": "MSET008 original PDF, p7, Q22", "review_note": "Original graph restored and all multiplicities and signs checked.", "explanation": "The graph touches the x-axis at x = 1, so that zero has even multiplicity, and crosses at x = 2 and x = 4. Both ends point down, requiring an even degree and a negative leading coefficient. These features give g(x) = −(x − 1)²(x − 2)(x − 4), choice B.", "correct": "B", "release": true, "before": {"stem": "The function $y=g(x)$ is graphed in the xy-plane. Which of the following equations could describe $g(x)$?", "choices": [{"key": "A", "text": "$g(x)=(x+1)(x+2)(x-4)^2$"}, {"key": "B", "text": "$g(x)=-(x-1)^2(x-2)(x-4)$"}, {"key": "C", "text": "$g(x)=(x-1)^2(x-2)(x+4)$"}, {"key": "D", "text": "$g(x)=(x+1)^2(x+2)(x+4)$"}], "correct": "B", "explanation": "The graph shows all intercepts at positive x-values, ruling out A, C and D, which each place at least one root negative. B has roots at 1 (touching, from the squared factor), 2 and 4, with a leading negative sign matching the graph's end behaviour."}, "fields": {"assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "f9cb2245-1c9b-413d-b82f-2fe74245e7e3", "source": "MSET008 original PDF, p11, Q39", "review_note": "Verified that side d is the leg CE adjacent to angle C.", "explanation": "cos C = adjacent/hypotenuse = d/10 = 1/2. Therefore d = 10(1/2) = 5 centimeters.", "correct": "5", "release": true, "before": {"stem": "In right triangle $CDE$, $\\cos C=\\frac12$. If the hypotenuse is 10 centimeters long, what is the length of side $d$?", "choices": [], "correct": "5", "explanation": "Side $d$ is the side adjacent to angle $C$. Since $\\cos C=\\frac{\\text{adjacent}}{\\text{hypotenuse}}=\\frac{d}{10}=\\frac12$, we get $d=5$."}, "fields": {"stem": "In right triangle CDE shown, ∠E = 90°, side CE is labeled d, and cos C = 1/2. If the hypotenuse CD is 10 centimeters long, what is d?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "dc92b671-81dd-42bf-9d99-d21c2daf1413", "source": "MSET008 original PDF, p12, Q44", "review_note": "Recreated the verified original geometry without handwritten solution annotations; B is on the positive x-axis and A in quadrant I.", "explanation": "Since OB lies on the positive x-axis, tan(π/3) = (2√3)/x. Thus √3 = 2√3/x and x = 2.", "correct": "2", "release": true, "before": {"stem": "In the xy-plane, $O$ is the center of the circle, point $A$ is at $(x,2\\sqrt3)$, and the measure of $\\angle AOB$ is $\\frac\\pi3$. What is the value of $x$?", "choices": [], "correct": "2", "explanation": "With $B$ on the positive x-axis, the angle at the origin satisfies $\\tan\\frac\\pi3=\\frac{2\\sqrt3}{x}$. Since $\\tan60°=\\sqrt3$, we get $\\sqrt3x=2\\sqrt3$, so $x=2$."}, "fields": {"stem": "In the xy-plane, the circle is centered at O = (0,0). Point B lies on the positive x-axis, and A = (x, 2√3) lies in the first quadrant. If ∠AOB = π/3, what is x?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/svg+xml;base64,"}}}, {"id": "367e0ba3-bac4-48ca-a038-c202281d1795", "source": "MSET008 original PDF, p13, Q46", "review_note": "Original first-quadrant point and positive x-axis reference verified.", "explanation": "With OB on the positive x-axis, tan(π/6) = y/(3√3). Since tan(π/6) = 1/√3, y = 3√3/√3 = 3.", "correct": "3", "release": true, "before": {"stem": "In the xy-plane, $O$ is the center of the circle, point $A$ is at $(3\\sqrt3,y)$, and the measure of $\\angle AOB$ is $\\frac\\pi6$. What is the value of $y$?", "choices": [], "correct": "3", "explanation": "With $B$ on the positive x-axis, $\\tan\\frac\\pi6=\\frac{y}{3\\sqrt3}$. Since $\\tan30°=\\frac1{\\sqrt3}$, we get $y=\\frac{3\\sqrt3}{\\sqrt3}=3$."}, "fields": {"stem": "The circle shown is centered at O = (0,0). Point B lies on the positive x-axis, and A = (3√3, y) lies in the first quadrant. If ∠AOB = π/6, what is y?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "ee488875-3cb3-48f0-896f-8f1671748e84", "source": "College Board question ecc98c87, supplied PDF p3", "review_note": "Recovered original transversal diagram and independently checked each proposed condition.", "explanation": "Angles w and y occupy corresponding positions relative to transversal k. If y = 147°, then y = w, so the converse of the corresponding-angles theorem proves r ∥ s. The equations x = 33 and y + z = 180 describe linear pairs that hold without parallel lines. The condition w + y = 180 would not make these corresponding angles equal.", "correct": "B", "release": true, "before": {"stem": "In the figure shown, line $k$ intersects lines $r$ and $s$. If $w=147$, which additional piece of information is sufficient to prove that lines $r$ and $s$ are parallel?", "choices": [{"key": "A", "text": "$x=33$"}, {"key": "B", "text": "$y=147$"}, {"key": "C", "text": "$w+y=180$"}, {"key": "D", "text": "$y+z=180$"}], "correct": "B", "explanation": "The angles marked $w°$ and $y°$ are corresponding angles for the transversal $k$. Two lines cut by a transversal are parallel if and only if a pair of corresponding angles is congruent. Given $w=147$, knowing $y=147$ makes them congruent and proves the lines parallel. Choice A fails because $x°$ and $w°$ form a linear pair, so $x=33$ follows automatically whether or not the lines are parallel. Choice C gives $y=33$, making the corresponding angles unequal. Choice D describes a linear pair at line $s$, true regardless."}, "fields": {"assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260929' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260929','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260929','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-29-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-29-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-29-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260929','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260929'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260929')) AS result;
